import { encodeFilePath } from "@opencode/util/path";
/** The file:// URL of a workspace-relative path. */
export function workspaceFileURL(files, path) {
    return `file://${encodeFilePath(`${files.root.replaceAll("\\", "/").replace(/\/+$/, "")}/${path}`)}`;
}
